import java.util.*;

public class Main {
    static boolean isvalid(long x) {
        if (x < 1 || x > 1000000000L) {
            return false;
        }
        String s = Long.toString(x);
        Set<Character> set = new HashSet<>();
        for (char c : s.toCharArray()) {
            set.add(c);
        }
        return set.size() <= 2;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        Set<Long> curr = new HashSet<>();
        for (int i = 1; i < 100; i++) {
            curr.add((long) i);
        }

        long cnt = 0;
        while (cnt <= 100000) {
            Set<Long> curr1 = new HashSet<>();
            for (long i : curr) {
                for (int j = 0; j < 10; j++) {
                    long val = i * 10 + j;
                    if (isvalid(val)) {
                        curr1.add(val);
                        cnt++;
                    }
                }
            }
            curr.addAll(curr1);
        }

        List<Long> currList = new ArrayList<>(curr);
        Collections.sort(currList);

        long ans = 0;
        for (long i : currList) {
            if (i >= 1 && i <= n) {
                ans++;
            } else if (i > n) {
                break;
            }
        }

        System.out.println(ans);
    }
}

